    /** Move a claim to another status; refused when the user's role may not open, settle or void it (the
     *  sheet's permission matrix), when its current status does not allow it,
     *  or when the user settling it is the one who opened it. A clerk settling a claim whose due is above
     *  the sheet's clerk limit (a due of n/a is within any limit) puts it PENDING instead, for a steward to
     *  approve or reject; its due stays live. Settling fixes the
     *  claim's due at its grade's rate in force on its date (a claim bound by a statement at the figure it
     *  bound), its late charge on the sheet's today frozen in on top; with no figure then, its due stays live. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to) {
        return changeStatus(sheetId, user, claimId, to, "");
    }

    /** Void a claim (see changeStatus): while the sheet has void reasons, with one of them, which it keeps;
     *  a void without one, or with one not on the list, is refused. */
    @Transactional
    public Claim voidClaim(String sheetId, String user, long claimId, String reason) {
        return changeStatus(sheetId, user, claimId, ClaimStatus.VOID, reason);
    }

    private Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus to, String voidReason) {
        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        refuseClosed(sheetId, claim.getDueBy());
        roles.require(sheetId, user, switch (to) {
            case OPEN -> "open";
            case SETTLED, PENDING -> "settle";
            case VOID -> "void";
            case DRAFT, DELETED, REVIEW -> throw new IllegalStateException();
        });
        if (!claim.getStatus().canBecome(to)) {
            throw new ClaimStatusException(claim.getStatus(), to);
        }
        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
            refuseVoidSettled(claim, sheetId, user);
        }
        if (to == ClaimStatus.VOID) {
            refuseVoidReason(sheetId, voidReason);
        }
        String reversed = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED
                ? " reversed=" + show(claim.getSettledDue()) : "";
        if (to == ClaimStatus.VOID && !voidReason.isEmpty()) {
            reversed += " reason=" + voidReason;
        }
        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ClaimSettlerException("The user who opened a claim cannot settle it.");
        }
        if (to == ClaimStatus.SETTLED && user.equals(claim.getEditedBy())) {
            throw new ClaimSettlerException("The user who last edited a claim cannot settle it.");
        }
        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
            throw new ClaimDeferException("The claim is deferred until " + claim.getDeferredUntil() + ".");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        if (to == ClaimStatus.OPEN) {
            refuseNoteless(claim, shownDue(claim, person));
            refuseOverCap(claim);
        }
        Rollup.Snapshot before = rollup.take(sheetId);
        String number = claim.getNumber();
        if (to == ClaimStatus.OPEN && overReviewThreshold(claim, shownDue(claim, person))) {
            to = ClaimStatus.REVIEW;
            claim.setOpenedBy(user);
        } else if (to == ClaimStatus.OPEN) {
            number = sheets.nextClaimNumber(sheetId, claim.getDueBy());
            claim.setOpenedBy(user);
        }
        if (to == ClaimStatus.SETTLED) {
            BigDecimal figure = claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
            BigDecimal due = figure == null ? null : charged(claim, person, figure);
            refuseUnproved(claim, person, due);
            if (overLimit(sheetId, user, due)) {
                to = ClaimStatus.PENDING;
            } else {
                claim.setSettledDue(due);
            }
        }
        claim.setStatus(to);
        claim.setNumber(number);
        if (to == ClaimStatus.VOID) {
            claim.setVoidReason(voidReason.isEmpty() ? null : voidReason);
        }
        logStatus(claim, person, user);
        Claim updated = claims.saveAndFlush(claim);
        String event = switch (to) {
            case OPEN -> "CLAIM_OPENED";
            case REVIEW -> "CLAIM_REVIEW";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT, DELETED -> throw new IllegalStateException();
        };
        audit(event, updated, person, user, number, to == ClaimStatus.SETTLED ? dueField(updated) : reversed);
        if (to == ClaimStatus.SETTLED) {
            notifyWatchers(updated, person, user);
        }
        rollup.recordChanges(sheetId, user, before);
        return updated;
    }
    }

    /** What a bulk open did: how many it opened and refused, and the claims it opened. */
    public record BulkOpened(int opened, int refused, List<Claim> claims) {
    }

    /** Open the chosen claims together, numbering them in list order (people in the order they were added,
     *  each person's claims newest first); a claim that cannot be opened is left as it is and counted as
     *  refused, as is one not on the sheet. */
    @Transactional
    public BulkOpened bulkOpen(String sheetId, String user, Collection<Long> claimIds) {
        Set<Long> chosen = new HashSet<>(claimIds);
        if (roles.isViewer(sheetId, user) || sheets.isArchived(sheetId)) {
            return new BulkOpened(0, chosen.size(), List.of());
        }
        List<Claim> opened = new ArrayList<>();
        for (Claim claim : inListOrder(sheetId, chosen)) {
            try {
                opened.add(changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
            } catch (ClaimStatusException | PeriodClosedException | ClaimNotFoundException
                    | ActionNotAllowedException | ClaimNoteException | ClaimCapException e) {
                // refused: left as it is
            }
        }
        return new BulkOpened(opened.size(), chosen.size() - opened.size(), opened);
    }

    /** What a bulk settle did: how many it settled (PENDING included) and refused, the claims it changed, and
     *  the number of the batch it made (none when it settled none). */
    public record BulkSettled(int settled, int refused, List<Claim> claims, Integer batch) {
    }
 * The paste box: lines of name,amount,date,note (the note may hold commas and may be absent; a blank date
 * takes the sheet's entry date, its today when off), each a DRAFT claim for the person on the sheet with
 * the name or an alias (ignoring case), added in order. A note ending in " #<reference>" gives the claim that external
 * reference, which is not part of the note. Blank lines are skipped. One change: every line is checked
 * with the claim form's rules (a reference used twice in the paste too, ignoring case), and a refused line
 * refuses the paste, adding nothing and writing nothing.
 * <p>
 * Each line's claim is then opened by the user as the open button would, in paste order; any refusal the
 * open would give refuses the whole paste. A line naming a person, date and note matching one of their
 * claims as they stood before the paste (void and deleted ones aside) updates that claim instead: the
 * newest matching DRAFT takes the line's amount and is opened; matches with no DRAFT refuse the paste.
 */
@Service
public class PasteService {

    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,13}(\\.\\d{1,2})?");
    private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    private final PersonRepository people;
    private final ClaimService claims;
    private final ClaimRepository claimsRepo;
    private final SheetService sheets;

    public PasteService(PersonRepository people, ClaimService claims, ClaimRepository claimsRepo,
            SheetService sheets) {
        this.people = people;
        this.claims = claims;
        this.claimsRepo = claimsRepo;
        this.sheets = sheets;
    }

    private record Line(int number, Person person, BigDecimal amount, LocalDate date, String note,
            String ref) {
    }

    /** The claims added, in the order of their lines. */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Line> lines = new ArrayList<>();
        Set<String> refs = new HashSet<>();
        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
        for (int i = 0; i < raw.length; i++) {
            if (!raw[i].isBlank()) {
                Line line = parse(sheetId, i + 1, raw[i]);
                if (line.ref() != null && !refs.add(line.ref().toLowerCase(Locale.ROOT))) {
                    throw refused(line.number(), "the reference " + line.ref() + " is already in this paste.");
                }
                lines.add(line);
            }
        }
        if (lines.isEmpty()) {
            throw new ClaimPasteException("Paste at least one line of name,amount,date,note.");
        }
        List<Claim> before = claimsRepo.findBySheetIdOrderByListOrderDesc(sheetId);
        LocalDate entry = sheets.entryDefault(sheetId);
        List<Optional<Claim>> matched = new ArrayList<>();
        Set<Long> taken = new HashSet<>();
        for (Line line : lines) {
            Optional<Claim> match = match(before, line, line.date() != null ? line.date() : entry);
            if (match.isPresent() && !taken.add(match.get().getId())) {
                throw refused(line.number(), "its claim is already updated by an earlier line.");
            }
            matched.add(match);
        }
        List<Claim> done = new ArrayList<>();
        for (int i = 0; i < lines.size(); i++) {
            Line line = lines.get(i);
            try {
                Claim claim;
                if (matched.get(i).isPresent()) {
                    claim = matched.get(i).get();
                    if (claim.getAmount().compareTo(line.amount()) != 0) {
                        claims.update(sheetId, user, claim.getId(), line.amount(), claim.getDate(), claim.getNote(),
                                claim.getCorrects(), line.ref() != null ? line.ref() : claim.getRef(),
                                List.copyOf(claim.getTags()));
                    }
                } else {
                    claim = claims.add(sheetId, user, line.person().getId(), line.amount(), line.date(),
                            line.note(), null, line.ref(), List.of());
                }
                done.add(claims.changeStatus(sheetId, user, claim.getId(), ClaimStatus.OPEN));
            } catch (PeriodClosedException | PersonRetiredException | ClaimCorrectionException
                    | ClaimRefException | ClaimStatusException | ClaimNotDraftException | ClaimLockedException
                    | ClaimLineException | ClaimNoteException | ClaimCapException | ActionNotAllowedException e) {
                throw new ClaimPasteException("Line " + line.number() + ": " + e.getMessage());
            }
        }
        return done;
    }

    /** The newest DRAFT of the line's person with its date and note, among the claims before the paste;
     *  none when nothing matches. A line matching only claims that are not DRAFTs is refused. */
    private static Optional<Claim> match(List<Claim> before, Line line, LocalDate date) {
        List<Claim> matches = before.stream()
                .filter(c -> c.getPersonId().equals(line.person().getId()))
                .filter(c -> c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED)
                .filter(c -> date.equals(c.getDate()))
                .filter(c -> line.note().equals(c.getNote() == null ? "" : c.getNote().trim()))
                .toList();
        if (matches.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(matches.stream().filter(c -> c.getStatus() == ClaimStatus.DRAFT).findFirst()
                .orElseThrow(() -> refused(line.number(), "its matching claim is no longer a DRAFT.")));
    }

    private Line parse(String sheetId, int number, String raw) {
        String[] f = raw.split(",", 4);
        String name = f[0].trim();
        if (name.isEmpty() || name.length() > 200) {
            throw refused(number, "enter a name.");
        }
        Person person = people.findByNameOrAlias(sheetId, name)
                .orElseThrow(() -> refused(number, "no one on the sheet is named " + name + "."));
        String amount = f.length > 1 ? f[1].trim() : "";
        if (!AMOUNT.matcher(amount).matches()) {
            throw refused(number, "enter an amount with up to two decimals.");
        }
        String date = f.length > 2 ? f[2].trim() : "";
        LocalDate on = null;
        if (!date.isEmpty()) {
            try {
                on = LocalDate.parse(date, DATE);
            } catch (DateTimeParseException e) {
                throw refused(number, "enter a date as YYYY-MM-DD.");
            }
        }
        String note = f.length > 3 ? f[3].trim() : "";
        String ref = null;
        int hash = note.lastIndexOf(" #");
        if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
            ref = note.substring(hash + 2).trim();
            note = note.substring(0, hash).trim();
        }
        if (note.length() > 1000) {
            throw refused(number, "the note is too long.");
        }
        if (ref != null && ref.length() > 200) {
            throw refused(number, "the reference is too long.");
        }
        return new Line(number, person, new BigDecimal(amount), on, note, ref);
    }

    private static ClaimPasteException refused(int number, String why) {
        return new ClaimPasteException("Line " + number + ": " + why);
    }
}

